from core.base import Language
from core.translate import TRANSPILERS


PIKA_TO_BF = {
    "pikachu":   "[", "pikapika":  "]",
    "pikapi":    ">", "pik":       "<",
    "pi":        "+", "ka":        "-",
    "pika":      ".", "kapi":      ",",
}
BF_TO_PIKA = {
    "[": "pikachu ", "]": "pikapika ",
    ">": "pikapi ",  "<": "pik ",
    "+": "pi ",      "-": "ka ",
    ".": "pika ",    ",": "kapi ",
}


def _pika_to_bf(src):
    keys = sorted(PIKA_TO_BF.keys(), key=len, reverse=True)
    bf = []
    i = 0
    while i < len(src):
        matched = False
        for key in keys:
            if src.startswith(key, i):
                bf.append(PIKA_TO_BF[key])
                i += len(key)
                matched = True
                break
        if not matched:
            i += 1
    return "".join(bf)


def _pika_to_python(src):
    bf = _pika_to_bf(src)
    lines = ["_tape = [0] * 30000", "_ptr = 0"]
    for c in bf:
        if c == '>':
            lines.append("_ptr = (_ptr + 1) % 30000")
        elif c == '<':
            lines.append("_ptr = (_ptr - 1) % 30000")
        elif c == '+':
            lines.append("_tape[_ptr] = (_tape[_ptr] + 1) & 0xFF")
        elif c == '-':
            lines.append("_tape[_ptr] = (_tape[_ptr] - 1) & 0xFF")
        elif c == '.':
            lines.append("print(chr(_tape[_ptr]), end='')")
    return "\n".join(lines) + "\n"


def _pika_print(text):
    """Pika-код, печатающий текст. Перед каждым символом сбрасывает ячейку."""
    parts = []
    for ch in text:
        n = ord(ch) & 0xFF
        parts.append("pikachu ka pikapika ")   # [-]
        parts.append("pi " * n)                 # + × n
        parts.append("pika ")                   # .
    return "".join(parts)


